 function anchorText(id:string){const n=data.notes.find(n=>n.id===id);if(n)return `${!n.parent?'核心问题':noteNumber(n)} ${n.title}`;const c=data.crossThoughts.find(c=>c.id===id);if(c)return `${crossCode(c)} ${c.title||c.text||'未命名关联主题'}`;const t=ordinaryThoughts.find(t=>t.id===id);return t?`${t.ownerLabel} 的思考：${short(t.text,70)}`:'来源暂不可见';}
