 function openHistoryEntry(entry:HistoryEntry){if(entry.archive){setHistoryOpen(false);setMaintenanceOpen(true);return;}if(entry.pageId){setHistoryOpen(false);selectPage(entry.pageId);return;}if(entry.readingId){setHistoryOpen(false);openReading(entry.readingId);return;}if(entry.bookThoughtId){const thought=data.bookThoughts.find(item=>item.id===entry.bookThoughtId);if(thought){const source=thoughtPrimary(thought,data.libraryBooks);if(source?.libraryBookId){if(thoughtSources(thought).length>1)startComparison(source,thought);else openBook(source.libraryBookId,source.sourceLocation,thought.id);}else openDetachedBookThought(thought.id);}setHistoryOpen(false);return;}
  setHistoryOpen(false);
  if(entry.manuscriptId){openManuscript(entry.manuscriptId);return;}
  const replyId=entry.id.startsWith('reply:')?entry.id.slice(6):undefined;
  const thoughtId=replyId?data.thoughtReplies.find(reply=>reply.id===replyId)?.thoughtId:entry.id.startsWith('thought:')?entry.id.slice(8):undefined;
  if(thoughtId){
   const reading=data.readingNotes.find(item=>item.thoughts.some(thought=>thought.id===thoughtId));if(reading){openReading(reading.id,thoughtId);return;}
   const bookThought=data.bookThoughts.find(item=>item.thoughts.some(thought=>thought.id===thoughtId));if(bookThought){const primary=thoughtPrimary(bookThought,data.libraryBooks);if(primary?.libraryBookId)openBook(primary.libraryBookId,primary.sourceLocation,bookThought.id);else openDetachedBookThought(bookThought.id);return;}
   openItem(entry.ownerId,thoughtId,replyId);return;
  }
  openItem(entry.ownerId);
 }
